const provisionAcceptanceLock = `-- name: ProvisionAcceptanceLock :exec
INSERT INTO ingest.acceptance_lock (revision_key, processing_attempt_key)
VALUES ($1::text, $2::text)
ON CONFLICT (revision_key, processing_attempt_key) DO NOTHING
`

type ProvisionAcceptanceLockParams struct {
	RevisionKey          string
	ProcessingAttemptKey string
}

// Acceptance never registers blobs or takes the blob catalog guard. The caller
// holds admission and one document-version lease before these statements.
// Provision and lock are separate statements for READ COMMITTED visibility.
func (q *Queries) ProvisionAcceptanceLock(ctx context.Context, arg ProvisionAcceptanceLockParams) error {
	_, err := q.db.Exec(ctx, provisionAcceptanceLock, arg.RevisionKey, arg.ProcessingAttemptKey)
	return err
}

const readAcceptanceAttempt = `-- name: ReadAcceptanceAttempt :one
SELECT s.id, s.acceptance_id, s.state, s.watermark,
    a.candidate_digest, a.quality_report_hash, a.execution_result_id,
    (s.revision_key = a.revision_key
     AND s.processing_attempt_key = a.processing_attempt_key
     AND s.state = a.state AND s.watermark = a.watermark
     AND a.execution_result_id = r.id AND a.watermark = r.id
     AND a.execution_id = r.execution_id) AS consistent
FROM ingest.revision_acceptance_state s
JOIN ingest.revision_acceptance a ON a.id = s.acceptance_id
JOIN ingest.execution_result r ON r.id = a.execution_result_id
WHERE s.revision_key = $1::text
  AND s.processing_attempt_key = $2::text
FOR UPDATE OF s
`

type ReadAcceptanceAttemptParams struct {
	RevisionKey          string
	ProcessingAttemptKey string
}

type ReadAcceptanceAttemptRow struct {
	ID                int64
	AcceptanceID      int64
	State             string
	Watermark         int64
	CandidateDigest   string
	QualityReportHash string
	ExecutionResultID int64
	Consistent        pgtype.Bool
}

// Lock the projection only, never its immutable event or result.
func (q *Queries) ReadAcceptanceAttempt(ctx context.Context, arg ReadAcceptanceAttemptParams) (ReadAcceptanceAttemptRow, error) {
	row := q.db.QueryRow(ctx, readAcceptanceAttempt, arg.RevisionKey, arg.ProcessingAttemptKey)
	var i ReadAcceptanceAttemptRow
	err := row.Scan(
		&i.ID,
		&i.AcceptanceID,
		&i.State,
		&i.Watermark,
		&i.CandidateDigest,
		&i.QualityReportHash,
		&i.ExecutionResultID,
		&i.Consistent,
	)
	return i, err
}

const readAcceptanceBaseline = `-- name: ReadAcceptanceBaseline :one
SELECT a.id, a.revision_key, a.processing_attempt_key, a.candidate_digest,
    a.quality_report_hash, a.watermark
FROM ingest.revision_acceptance a
JOIN ingest.revision_acceptance_state s ON s.acceptance_id = a.id
  AND s.revision_key = a.revision_key
  AND s.processing_attempt_key = a.processing_attempt_key
  AND s.state = a.state AND s.watermark = a.watermark
WHERE s.state IN ('accepted', 'accepted_with_gaps')
  AND split_part(a.revision_key, ':rev:', 1) = $1::text
  AND a.watermark < $2::bigint
ORDER BY a.watermark DESC, a.id DESC LIMIT 1
`

type ReadAcceptanceBaselineParams struct {
	IdentityKey     string
	BeforeWatermark int64
}

type ReadAcceptanceBaselineRow struct {
	ID                   int64
	RevisionKey          string
	ProcessingAttemptKey string
	CandidateDigest      string
	QualityReportHash    string
	Watermark            int64
}

func (q *Queries) ReadAcceptanceBaseline(ctx context.Context, arg ReadAcceptanceBaselineParams) (ReadAcceptanceBaselineRow, error) {
	row := q.db.QueryRow(ctx, readAcceptanceBaseline, arg.IdentityKey, arg.BeforeWatermark)
	var i ReadAcceptanceBaselineRow
	err := row.Scan(
		&i.ID,
		&i.RevisionKey,
		&i.ProcessingAttemptKey,
		&i.CandidateDigest,
		&i.QualityReportHash,
		&i.Watermark,
	)
	return i, err
}

const readAcceptanceEvent = `-- name: ReadAcceptanceEvent :many
SELECT id, revision_key, processing_attempt_key, execution_id,
    execution_result_id, candidate_digest, quality_report_hash,
    decision_revision, state, watermark
FROM ingest.revision_acceptance
WHERE execution_result_id = $1::bigint
ORDER BY id LIMIT 2
`

type ReadAcceptanceEventRow struct {
	ID                   int64
	RevisionKey          string
	ProcessingAttemptKey string
	ExecutionID          int64
	ExecutionResultID    int64
	CandidateDigest      string
	QualityReportHash    string
	DecisionRevision     int64
	State                string
	Watermark            int64
}

// A historical result retains its original immutable event after projection changes.
func (q *Queries) ReadAcceptanceEvent(ctx context.Context, executionResultID int64) ([]ReadAcceptanceEventRow, error) {
	rows, err := q.db.Query(ctx, readAcceptanceEvent, executionResultID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReadAcceptanceEventRow
	for rows.Next() {
		var i ReadAcceptanceEventRow
		if err := rows.Scan(
			&i.ID,
			&i.RevisionKey,
			&i.ProcessingAttemptKey,
			&i.ExecutionID,
			&i.ExecutionResultID,
			&i.CandidateDigest,
			&i.QualityReportHash,
			&i.DecisionRevision,
			&i.State,
			&i.Watermark,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const readAcceptanceJSON = `-- name: ReadAcceptanceJSON :one
WITH selected AS (
    SELECT e.budget AS value FROM ingest.execution e WHERE $2::text = 'budget' AND e.execution_key = $3::text
    UNION ALL SELECT e.run_receipts FROM ingest.execution e WHERE $2::text = 'receipts' AND e.execution_key = $3::text
    UNION ALL SELECT r.payload FROM ingest.execution_result r WHERE $2::text = 'payload' AND r.idempotency_key = $3::text
    UNION ALL SELECT a.scoped_gaps FROM ingest.revision_acceptance a WHERE $2::text = 'gaps' AND a.id::text = $3::text
    UNION ALL SELECT p.manifest FROM config.policy_bundle p WHERE $2::text = 'policy' AND p.digest = $3::text
    UNION ALL SELECT d.evidence FROM ingest.quarantine_decision d WHERE $2::text = 'decision' AND d.decision_key = $3::text
)
SELECT value::jsonb AS value FROM selected
WHERE octet_length(value::text)::bigint = $1::bigint
`

type ReadAcceptanceJSONParams struct {
	ByteSize int64
	Kind     string
	Identity string
}

func (q *Queries) ReadAcceptanceJSON(ctx context.Context, arg ReadAcceptanceJSONParams) (json.RawMessage, error) {
	row := q.db.QueryRow(ctx, readAcceptanceJSON, arg.ByteSize, arg.Kind, arg.Identity)
	var value json.RawMessage
	err := row.Scan(&value)
	return value, err
}

